// static
bool StructTraits<::ash::help_app::mojom::DeviceInfo::DataView, ::ash::help_app::mojom::DeviceInfoPtr>::Read(
    ::ash::help_app::mojom::DeviceInfo::DataView input,
    ::ash::help_app::mojom::DeviceInfoPtr* output) {
  bool success = true;
  ::ash::help_app::mojom::DeviceInfoPtr result(::ash::help_app::mojom::DeviceInfo::New());
  
      if (success && !input.ReadBoard(&result->board))
        success = false;
      if (success && !input.ReadModel(&result->model))
        success = false;
      if (success && !input.ReadUserType(&result->user_type))
        success = false;
      if (success)
        result->is_steam_allowed = input.is_steam_allowed();
  *output = std::move(result);
  return success;
}

